            FeedItem("دعا: غم اور پریشانی میں", "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ", "اے اللہ، میں غم اور پریشانی سے تیری پناہ مانگتی ہوں", "صحیح البخاری", "dua"),
