        private val allFeeds: Map<String, List<FeedItem>> = mapOf(
            "fatwa" to satFatwa,
            "sahabiyat" to sunSahabiyat,
            "ayah" to monAyah,
            "hadith" to tueHadith,
            "fiqh" to wedFiqh,
            "dua" to thuDua,
            "jumuah" to friJumuah
        )

        private val dayCategories = mapOf(
            Calendar.SATURDAY to "fatwa",
            Calendar.SUNDAY to "sahabiyat",
            Calendar.MONDAY to "ayah",
            Calendar.TUESDAY to "hadith",
            Calendar.WEDNESDAY to "fiqh",
            Calendar.THURSDAY to "dua",
            Calendar.FRIDAY to "jumuah"
        )
    }

    fun getTodayCategory(): String {
        val day = Calendar.getInstance().get(Calendar.DAY_OF_WEEK)
        return dayCategories[day] ?: "ayah"
    }

    fun getTodaysFeed(): FeedItem {
        val category = getTodayCategory()
        val feeds = allFeeds[category] ?: monAyah
        val weekIndex = (Calendar.getInstance().get(Calendar.WEEK_OF_YEAR) - 1) % feeds.size
        return feeds[weekIndex.coerceIn(0, feeds.size - 1)]
    }
}
